#pragma once

/* Base version of the WebKit Autoloader (WKAL) content.
 * Bump this when the autoloader frontend changes — it triggers the app-cache
 * update and also marks the matching WKALI installer build. */
#define WKAL_VERSION "0.8.0"

/* Full build version (stable: <base>, dev: <base>-dev-<hash|timestamp>),
 * generated by tools/gen_version.py - see include/wkali_version.h.
 *
 * The same header also carries the per-variant identity (make VARIANT=
 * auto|poops|relapse, table in tools/gen_version.py):
 *   WKAL_VARIANT, WKAL_APP_NAME  - variant id and homescreen app name
 *   WKAL_TITLE_ID                - title ID of the installed homescreen app
 *   WKALI_PORT                   - installer/app port; also the deeplink port
 *                                  in assets/param.json, so each variant gets
 *                                  its own WebKit origin and AppCache
 *   WKALI_THREAD_NAME            - used to kill stale installer instances */
#include "wkali_version.h"

/* Routes */
#define ROUTE_INDEX "/"
#define ROUTE_INDEX_HTML "/index.html"
#define ROUTE_CACHE_MANIFEST "/cache.appcache"
#define ROUTE_INSTALL "/install"
#define ROUTE_VERSION "/version"
#define ROUTE_CLEAR_WEBKIT_DATA "/clear-webkit-data"
#define ROUTE_EXIT "/exit"

/* Native platform helpers are owned by remote-loader. */
#include "installer_support.h"
